use vstd::prelude::*;

verus! {

spec fn split_and_append_spec(s: Seq<i32>, n: nat) -> Seq<i32> {
    s.subrange(n, s.len()) + s.subrange(0, n)
}

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list@.len() > 0,
        0 < n,
        n < list@.len(),
    ensures
        new_list@ == split_and_append_spec(list@, n as nat),
        new_list@.len() == list@.len(),
{
    let len = list.len();
    assert!(len > 0, "list must be non-empty");
    assert!(n > 0 && n < len, "n must satisfy 0 < n < list.len()");

    let mut new_list = Vec::with_capacity(len);

    new_list.extend_from_slice(&list[n..]);
    // After first extend: new_list == suffix
    assert(new_list@ == list@.subrange(n as int, len as int));

    new_list.extend_from_slice(&list[..n]);
    // After second extend: new_list == suffix + prefix
    assert(new_list@ == list@.subrange(n as int, len as int) + list@.subrange(0, n as int));

    // Match the spec definition (n is known in-range by preconditions)
    assert(new_list@ == split_and_append_spec(list@, n as nat));

    new_list
}

} // verus!

